// RUN: %clang_cc1 -O2 -triple aie2ps -std=c++20 -emit-llvm -o - %s | FileCheck %s

extern void work(int *p, unsigned i);
extern void tail(int *p, unsigned i);

// CHECK-LABEL: define dso_local void @_Z8mid_exitPij(
// CHECK-SAME: ptr [[P:%.*]], i32 noundef [[ITERS:%.*]]) local_unnamed_addr #[[ATTR0:[0-9]+]] {
// CHECK-NEXT:  [[ENTRY:.*:]]
// CHECK-NEXT:    [[CMP8_NOT:%.*]] = icmp eq i32 [[ITERS]], 0
// CHECK-NEXT:    br i1 [[CMP8_NOT]], label %[[CLEANUP:.*]], label %[[FOR_BODY_LR_PH:.*]]
// CHECK:       [[FOR_BODY_LR_PH]]:
// CHECK-NEXT:    [[SUB:%.*]] = add i32 [[ITERS]], -1
// CHECK-NEXT:    tail call void @_Z4workPij(ptr [[P]], i32 noundef 0) #[[ATTR2:[0-9]+]]
// CHECK-NEXT:    [[CMP110:%.*]] = icmp eq i32 [[SUB]], 0
// CHECK-NEXT:    br i1 [[CMP110]], label %[[CLEANUP]], label %[[IF_END:.*]]
// CHECK:       [[IF_END]]:
// CHECK-NEXT:    [[IT_0911:%.*]] = phi i32 [ [[INC:%.*]], %[[IF_END]] ], [ 0, %[[FOR_BODY_LR_PH]] ]
// CHECK-NEXT:    tail call void @_Z4tailPij(ptr [[P]], i32 noundef [[IT_0911]]) #[[ATTR2]]
// CHECK-NEXT:    [[INC]] = add nuw i32 [[IT_0911]], 1
// CHECK-NEXT:    tail call void @_Z4workPij(ptr [[P]], i32 noundef [[INC]]) #[[ATTR2]]
// CHECK-NEXT:    [[CMP1:%.*]] = icmp eq i32 [[INC]], [[SUB]]
// CHECK-NEXT:    br i1 [[CMP1]], label %[[CLEANUP]], label %[[IF_END]]
// CHECK:       [[CLEANUP]]:
// CHECK-NEXT:    ret void
//
void mid_exit(int *p, unsigned iters) {
#pragma clang loop min_iteration_count(4) pipeline(disable)
  for (unsigned it = 0; it < iters; it++) {
    work(p, it);
    if (it == iters - 1)
      break;
    tail(p, it);
  }
}

// CHECK-LABEL: define dso_local void @_Z10latch_exitPij(
// CHECK-SAME: ptr [[P:%.*]], i32 noundef [[ITERS:%.*]]) local_unnamed_addr #[[ATTR0]] {
// CHECK-NEXT:  [[ENTRY:.*]]:
// CHECK-NEXT:    [[CMP5_NOT:%.*]] = icmp eq i32 [[ITERS]], 0
// CHECK-NEXT:    br i1 [[CMP5_NOT]], label %[[FOR_COND_CLEANUP:.*]], label %[[FOR_BODY:.*]]
// CHECK:       [[FOR_COND_CLEANUP]]:
// CHECK-NEXT:    ret void
// CHECK:       [[FOR_BODY]]:
// CHECK-NEXT:    [[IT_06:%.*]] = phi i32 [ [[INC:%.*]], %[[FOR_BODY]] ], [ 0, %[[ENTRY]] ]
// CHECK-NEXT:    tail call void @_Z4workPij(ptr [[P]], i32 noundef [[IT_06]]) #[[ATTR2]]
// CHECK-NEXT:    tail call void @_Z4tailPij(ptr [[P]], i32 noundef [[IT_06]]) #[[ATTR2]]
// CHECK-NEXT:    [[INC]] = add nuw i32 [[IT_06]], 1
// CHECK-NEXT:    [[EXITCOND_NOT:%.*]] = icmp eq i32 [[INC]], [[ITERS]]
// CHECK-NEXT:    br i1 [[EXITCOND_NOT]], label %[[FOR_COND_CLEANUP]], label %[[FOR_BODY]], !llvm.loop [[LOOP2:![0-9]+]]
//
void latch_exit(int *p, unsigned iters) {
#pragma clang loop min_iteration_count(4) pipeline(disable)
  for (unsigned it = 0; it < iters; it++) {
    work(p, it);
    tail(p, it);
  }
}
